{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/patterns/action-group.json
    One or two calls to action side by side: a filled primary button and an outline secondary one. Links, not handlers: the page decides what they open.
    Props (p): primary, primaryHref, secondary, secondaryHref, align. -#}
{%- set v_primary = ui_def(p['primary'], none) -%}
{%- set v_primaryHref = ui_def(p['primaryHref'], none) -%}
{%- set v_secondary = ui_def(p['secondary'], none) -%}
{%- set v_secondaryHref = ui_def(p['secondaryHref'], none) -%}
{%- set v_align = ui_def(p['align'], 'start') -%}
{%- set c_3 -%}
  {%- set c_1 -%}
    {{ ui_text(v_primary) }}
  {%- endset -%}
  {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': 'default', 'Size': 'default', 'Href': ui_s(v_primaryHref), 'Attrs': ui_attrs(['data-testid', 'action-primary'])}, 'children': c_1}) }}
  {%- if ui_t(v_secondary) %}
    {%- set c_2 -%}
      {{ ui_text(v_secondary) }}
    {%- endset -%}
    {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': 'outline', 'Size': 'default', 'Href': ui_s(v_secondaryHref), 'Attrs': ui_attrs(['data-testid', 'action-secondary'])}, 'children': c_2}) }}
  {%- endif %}
{%- endset -%}
{{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '4', 'Align': 'center', 'Justify': ui_s(('center' if ui_t(ui_eq(v_align, 'center')) else 'start')), 'Class': 'flex-wrap', 'Attrs': ui_attrs(['data-slot', 'action-group'])}, 'children': c_3}) }}
